@import url("chrome://messenger/skin/messenger.css");

#subscribeWindow,
dialog {
  min-inline-size: 40em;
  min-block-size: 30em;
}

#namefield {
  flex: 1;
  --input-text-max-width: none;
}

#treepanel > div {
  flex: 1 1 0;
  block-size: 0;
  align-items: stretch;
  display: flex;
}

#subscribeTree {
  flex: 1;
  margin-inline-end: 4px;
}
